if(!zh.hero.includes('精準 KB')||!zh.drop.includes('圖片')||!zh.guide.includes('使用說明')||zh.privacy!=='隱私說明'||zh.placeholder!=='不限')throw new Error(`zh translation incomplete ${JSON.stringify(zh)}`);
