async function typographyProfile(locale){await setLocale(locale);const rows=[];for(const w of widths){await page.setViewport({width:w,height:w<500?844:1000,deviceScaleFactor:1});await new Promise(r=>setTimeout(r,80));const profile=await page.evaluate(()=>{const measure=selector=>{const el=document.querySelector(selector);const walker=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);const lines=new Map();while(walker.nextNode()){const node=walker.currentNode;for(let i=0;i<node.textContent.length;i++){if(/\s/.test(node.textContent[i]))continue;const range=document.createRange();range.setStart(node,i);range.setEnd(node,i+1);const rect=range.getBoundingClientRect();if(!rect.width||!rect.height)continue;const key=Math.round(rect.top);const line=lines.get(key)||{left:rect.left,right:rect.right,chars:0};line.left=Math.min(line.left,rect.left);line.right=Math.max(line.right,rect.right);line.chars++;lines.set(key,line);} }const out=[...lines.values()].sort((a,b)=>a.left-b.left).map(line=>({width:Math.round(line.right-line.left),chars:line.chars}));const max=Math.max(...out.map(x=>x.width),1);return{text:el.textContent.trim(),lines:out,lastRatio:out.length>1?out.at(-1).width/max:1};};return{common:measure('.limit-copy h2'),guide:measure('#seoHeading'),overflow:document.documentElement.scrollWidth-innerWidth};});for(const [name,value] of Object.entries({common:profile.common,guide:profile.guide})){if(value.lines.length>1&&value.lastRatio<.34)throw new Error(`typography orphan ${locale} ${w}px ${name} ${JSON.stringify(value)}`);}if(profile.overflow>2)throw new Error(`typography overflow ${locale} ${w}px ${JSON.stringify(profile)}`);rows.push({w,...profile});}return rows;}
